from collections import Counter

def solution(A, B):
    # Count each array once. A value in both contributes min(count in A, count in B).
    count_a = Counter(A)
    count_b = Counter(B)
    if len(count_a) > len(count_b):
        count_a, count_b = count_b, count_a   # loop over the smaller one
    total = 0
    for value, times in count_a.items():
        if value in count_b:
            total += min(times, count_b[value])
    return total

